// Сгенерировано tools/build-base-media.mts: описания карточек справочника (TMDb), доля 05 из 16 по id
// (src/lib/shard.ts) — подгружается, когда раскрывают «Сюжет» (src/api, getPlot). Не править руками.
export const blurbs: Record<string, string> = {
 "f-wd57982486": "Сразу после празднования 85-летия, знаменитого автора детективов Харлана Тромби находят мёртвым в собственном особняке. Расследовать загадочную смерть берётся обаятельный и проницательный детектив Бенуа Блан. Ему предстоит распутать хитросплетения обмана, жадности и семейных тайн, окутавших этот дом, где каждый может оказаться подозреваемым, а правда — куда опаснее, чем кажется.",
 "f-wd1519753": "Провинциальный пилот Валико Мизандари по прозвищу Мимино, что значит «сокол», занимается вертолётными перевозками почты, фруктов, кур, баранов и даже коров в горных районах Грузинской ССР. Однажды встретив в Тбилисском аэропорту приятеля по лётному училищу и увидев, на каком великолепном сверхзвуковом самолёте тот летает и в компании каких красавиц-стюардесс работает, Мимино решает изменить свою жизнь и отправляется в Москву подавать документы на переобучение. В гостинице он оказывается в одном номере с армянским водителем Рубеном Хачикяном, которого ошибочно приняли за профессора-эндокринолога.",
 "f-wd115789958": "200 год нашей эры. Армия Римской империи под командованием генерала Марка Акация штурмует Нумидию — последнее свободное государство в Северной Африке. В битве с захватчиками у воина Ханно погибает супруга-лучница, а сам он попадает в плен. Вместе с другими пленникам его готовятся продать в рабство, но благодаря физической выносливости и боевым навыкам его замечает и покупает организатор гладиаторских боёв Макрин. Так воин становится гладиатором, одержимым жаждой мести римскому полководцу. Макрин обещает Ханно устроить встречу с его заклятым врагом, если парень будет эффектно, красочно и яростно сражаться на арене Колизея.",
 "f-wd27044293": "История об отважном львенке по имени Симба. Знакомые с детства герои взрослеют, влюбляются, познают себя и окружающий мир, совершают ошибки и делают правильный выбор.",
 "f-wd24515019": "…Как только что стало известно, сбитый над Москвой неопознанный объект имеет, возможно, внеземное происхождение. Большая часть столичного Чертаново оцеплена, к месту крушения стягиваются представители силовых структур, решается вопрос об эвакуации местных жителей. По словам нашего источника в Минобороны, сейчас специальная комиссия пытается вступить в контакт с так называемыми «гостями». В эти минуты мы готовим экстренный выпуск новостей и о развитии событий вы узнаете первыми…",
 "f-wd6144664": "Это история про обычную девочку, которую зовут Райли. Она, как и все другие дети или взрослые, имеет 5 основных видов эмоций, это — Страх, Гнев, Радость, Печаль и Брезгливость. Они помогают девочке разобраться в определённых ситуациях, в общем, руководят ею полностью, и, как правило действуют гармонично. Однажды родители героини решили переехать из маленького города в большой. Вот здесь-то гармония кардинально нарушается. Каждая эмоция считает, что для приспособления к новой среде должна действовать именно она. Но ничего из того не выйдет, пока взаимопонимание не восстановится между ними. Получится ли у них это сделать?",
 "f-wd14566553": "В центре сюжета сложные взаимоотношения выпускницы колледжа Анастейши Стил и молодого бизнесмена Кристиана Грея, который убеждает девушку подписать с ним контракт, позволяющий ему фактически контролировать всю ее жизнь. Условия контракта подразумевают также подписание соглашения о неразглашении, в результате чего Грей фактически может делать с Анастейшей все, что ему заблагорассудится.",
 "f-wd17042878": "События «Дней Минувшего Будущего» оказали колоссальное влияние на мир, где мутанты и люди борются за свое место под Солнцем. В это нелегкое время Людям Икс предстоит столкнуться со своим самым опасным противником — древним мутантом Апокалипсисом, существом, схватка с которым может стать последней не только для мутантов, но и в принципе для всего человечества. В поисках способа победы над неуязвимым и бессмертным монстром Людям Икс предстоит узнать больше о происхождении своего вида. Но Апокалипсис неимоверно силен, и вероятность победы все уменьшается, ведь он твердо убежден, что только сильнейшие имеют право на выживание…",
 "f-wd15270569": "Прогрессивные и талантливые Наташа и Рома мечтают о европейской свадьбе на берегу моря… но у Наташиного отчима заготовлен другой сценарий. Грубый чиновник городской администрации рассматривает торжество как трамплин для собственной карьеры и стремится устроить все «как надо». Молодых ждет незабываемый вечер в ресторане «Золотой» с полным набором занудных обрядов. Не в силах бороться, ребята решают провести свадьбу своей мечты в секрете от консервативных родственников. Но по нелепой случайности оба торжества сливаются воедино.",
 "f-wd131451703": "Когда военный эксперимент выходит из-под контроля, из сверхсекретной лаборатории вдали от цивилизации сбегает группа безжалостных суперсолдат — генетически модифицированных машин для убийств, уничтожающих всё живое на своём пути. Оставляя за собой кровавый след, они нападают на дом Селесты — и теперь ей придётся вспомнить все боевые навыки своего прошлого, чтобы защитить дочь.",
 "f-wd137754": "Рассказ о двух родственных душах, которым удалось найти друг друга в толчее дублинских улиц. Он — уличный музыкант, которому не достает уверенности в себе, чтобы исполнять свои собственные песни. Она — юная мать, пытающаяся найти свое место в этом чужом, новом для нее городе.  И как только они встречаются, каждому из них удается разглядеть в другом его талант и помочь осуществить то, о чем раньше лишь мечталось. «Однажды» — история любви этих двух людей.",
 "f-wd104044312": "Фильм посвящен реальной истории американского дизайнера игр и предпринимателя Хенка Роджерса, открывшего в 1988 игру «Тетрис». Решив поделиться своей находкой с миром, он попадает в опасную паутину лжи и коррупции за железным занавесом.",
 "f-wd130753385": "Малкольм приглашает Лиз на романтический уик-энд в свое фамильное имение в самом сердце леса. А затем, внезапно сославшись на неотложные дела, уезжает. Девушка остается один на один с огромным домом, из которого никак нельзя сбежать. И с каждой минутой находиться в нём становится всё опаснее. Если Лиз не разгадает его тайну, то останется здесь навечно.",
 "f-wd153484": "Элис приходит в себя в загадочном особняке, не помня, как туда попала. Вместе с полицейским Мэттом она оказывается втянута в опасную миссию, когда отряд спецназа проникает в подземный исследовательский комплекс корпорации «Амбрелла». Там произошла утечка смертельно опасного вируса, превратившего сотрудников лаборатории в кровожадных существ. Запертые внутри комплекса герои должны найти способ остановить распространение вируса и выбраться наружу, пока система безопасности не уничтожила всех, кто ещё остался в живых.",
 "f-wd63352785": "История о молодой паре, подыскивающей себе новое жилье. Некий агент по недвижимости заманивает их в пространство, оказывающееся лабиринтом, который не сулит героям ничего хорошего.",
 "f-wd24284283": "История о бесстрашной молодой девушке, которая выдаёт себя за мужчину, чтобы вступить в ряды армии, противостоящей Северным захватчикам, надвигающимся на Китай. Старшая дочь храброго воина Хуа, Мулан — энергичная и решительная девушка. Когда Император издаёт указ о том, что один мужчина из каждой семьи должен вступить в ряды Имперской армии, Мулан занимает место своего больного отца, еще не зная, что ей предстоит прославиться как одному из величайших воинов в истории Китая.",
 "f-wd28489891": "Лара Крофт - весьма самостоятельная дочь эксцентричного искателя приключений, который пропал, едва она стала подростком. Теперь ей двадцать один, она бесцельно проживает свою жизнь, курьером рассекая на байке по забитым улицам восточного Лондона, а ее заработка едва хватает на оплату квартиры и занятий в колледже. Решительно настроенная пробиться сама, она отказывается брать на себя руководство глобальной империей отца, столь же категорично отвергая мысль о том, что он действительно пропал. Слыша советы о том, что ей нужно смириться с этим фактом и жить дальше после семи лет бесплодных поисков, Лара уже и сама не понимает, что же заставляет ее распутывать обстоятельства его таинственной смерти.",
 "f-wd26698156": "Фильм повествует об отношениях существа-амфибии и девушки по имени Элайза на фоне противостояния США и СССР во времена Холодной войны. Скучная и одинокая жизнь Элайзы получает необычный поворот, когда она и коллега Зельда внезапно обнаруживают результаты эксперимента.",
 "f-wd21079862": "После череды побед Молния МакКуин сталкивается с новым поколением сверхбыстрых гоночных машин. Во главе с амбициозным Джексоном Штормом они используют современные технологии и методики подготовки, которые делают ветеранов трассы устаревшими. Во время одной из гонок МакКуин терпит тяжёлую аварию, и его карьера оказывается под угрозой. Чтобы вернуться в большой спорт, Молния начинает тренировки с молодой и энергичной Крус Рамирес. Вместе они ищут нестандартный подход к скорости, уверенности и вере в себя. МакКуину предстоит не просто выиграть очередную гонку, а понять, что значит быть настоящим чемпионом — и какую роль он готов сыграть в будущем мира гонок.",
 "f-wd10350033": "Капитан Джек Воробей вновь оказывается в смертельной опасности, когда за ним начинает охоту капитан Салазар — беспощадный призрачный моряк, сбежавший из таинственного Дьявольского треугольника. Единственный шанс спастись — найти легендарный Трезубец Посейдона, способный разрушить все морские проклятия. Вместе с молодым моряком Генри Тёрнером, который мечтает снять проклятие со своего отца Уилла Тёрнера и отважной астрономкой Кариной Смит Джек, он отправляется в новое путешествие, полное древних тайн, опасных сражений и неожиданных союзов, где судьба морей вновь оказывается под угрозой.",
 "f-wd1421902": "Время и место действия — Испания семнадцатого века, эпоха правления Филиппа Четвертого. Этим слабым, подверженным чужому влиянию монархом, с легкостью манипулирует его развращенный, полный интриг двор, где всем заправляет влиятельный граф Ольварес. В этой империи, которая неуклонно движется к своему закату, и разворачиваются приключения Диего Алатристе, гордого солдата на службе Его Величества во Фландрии, а в мирное время — наемника в Мадриде и Севилье. Вместе с этими персонажем мы попадем в мир интриг и предательств, дуэлей и битв, ненависти и любви, разыгранных на фоне удивительно точно реконструированной эпохи.",
 "f-wd55651410": "У Саши Королева была врожденная болезнь. Отец мальчика выбрал, как ему казалось, единственно правильный способ поставить сына на ноги — относиться к нему как к здоровому человеку. «Ты не больной — у тебя временные трудности».  Поесть, одеться, спуститься и подняться по лестнице подъезда — каждый день у ребенка уходили часы на то, чтобы справиться с простыми бытовыми задачами. В школе — издевательства сверстников. И помощи ждать было не от кого.  Мальчик справился с болезнью, но возненавидел отца. Окончив школу, Саша уехал из дома и прекратил всякое общение с отцом. За 15 лет он стал лучшим бизнес-консультантом страны, который вывел из кризиса сотни бизнесов. «У вас не кризис — у вас временные трудности» — говорил своим клиентам прошедший тяжелый путь становления Александр.  И однажды новый заказ дает ему неожиданную возможность поквитаться с отцом…",
 "f-wd116764712": "Джуди и Ник теперь полноценная команда в полиции. Но их спокойная служба резко меняется, когда в городе появляется загадочный преступник-рептилия, способный ставить под угрозу весь порядок в Зверополисе. Чтобы разобраться в деле, героям приходится углубиться в новые районы города, куда обычным жителям лучше не соваться. Расследование быстро выходит за рамки привычных правил: Джуди и Ник работают под прикрытием, сталкиваются с непредсказуемыми союзниками и опасными врагами, а также вынуждены доверять друг другу сильнее, чем когда-либо.",
 "f-wd85847274": "История Тима Балларда (Джим Кэвизел), бывшего агента правительства США, который уволился с работы, чтобы посвятить свою жизнь спасению детей от сексуального рабства.",
 "f-wd114802043": "Исследователи паранормальных явлений Эд и Лоррейн Уоррен берутся за самый тревожный случай в своей практике. Семья переезжает в новый дом своей мечты, но вскоре их жилище начинает проявлять признаки демонической активности, превращая жизнь в кошмар.",
 "f-wd4507452": "Новогодняя сказка о том, что настоящая любовь может творить чудеса. В институте «НУИНУ» (научный универсальный институт необыкновенных услуг) кипит бурная работа по изготовлению волшебной палочки. Презентация изобретения намечена на 31 декабря, в Новогодний вечер.",
 "f-wd123906765": "Молодой охотник на демонов Дэндзи, который ждал свидания со своей возлюбленной Макимой, попадает под ливень. Укрывшись от дождя, он случайно встречает девушку по имени Резе, работающую в соседнем кафе. Та добродушно ему улыбается, и разговор становится более непринужденным. После этой встречи повседневная жизнь Дэндзи начинает меняться.",
 "f-wd20899737": "Загадочная авария в туннелях под мостом-шоссе Токио Бэй Аква Лайн ставит на уши все аварийные подразделения мегаполиса. Шеф МЧС Японии созывает всех, чтобы найти причину аварии, и возможные решения сложившейся проблемы. Они еще не знают, что это только начало. Огромное существо, известное как Годзилла, встало на путь разрушения...",
 "f-wd752313": "Героиня этого фильма, Бриджет Джонс, решила, наконец, взять себя в руки и начать новую жизнь. Ей уже за тридцать, но она безвольно потакает своим вредным привычкам и не решается избавиться от лишних килограммов. Но, что самое главное, Бриджет — совсем одна. Родители пытаются сосватать ее за сына соседей, скромника Марка, а сама Бриджет без ума от своего неотразимого начальника Дэниэла! С первого дня новой жизни мисс Джонс решает вести дневник, в который она будет записывать свои будущие достижения и победы. Но оказалось, что осуществить мечты и найти истинную любовь гораздо сложней, чем это представлялось нашей прелестной героине...",
 "f-wd40302": "Экранизация книги Дэниэла П. Мэнникса. История про лисенка Тодда и щенка Коппера. Малыши были очень дружны, но когда подросли, одному природа уготовила роль охотника, другому, увы, объекта охоты.",
 "f-wd102235": "Гарри проводит свой пятый год в школе Хогвартс и обнаруживает, что многие из членов волшебного сообщества отрицают факт недавнего состязания юного волшебника с воплощением вселенского зла Волдемортом. Все делают вид, что не имеют ни малейшего представления, что злодей вернулся. Однако впереди волшебников ждет необычная схватка.",
 "f-wd19089": "Джеймс Бонд отправляется в Россию на поиски террористов, захвативших управление новым секретным оружейным комплексом «Золотой глаз». Разработанное для уничтожения любого компьютерного оборудования, в руках негодяев это оружие превращается в мощнейший инструмент давления на правительства экономически развитых государств. Во время этой чрезвычайно опасной миссии Бонду приходится полетать на вертолёте-невидимке, взорвать бронепоезд, совершить увлекательную поездку на танке по Санкт-Петербургу и, конечно, соблазнить парочку длинноногих красоток.",
 "f-wd188035": "1517 год. Полуостров Юкатан. В один день рушится мир индейца по имени Лапа Ягуара. Его деревню захватывает соседнее племя, уничтожая хижины, забирая местных жителей в плен. Его ведут в город, чтобы принести в жертву богам. Перед лицом неминуемой смерти Лапа Ягуара должен побороть свои самые сильные страхи и совершить отчаянный рывок, чтобы спасти то, что ему дорого.",
 "f-wd29054009": "Прошло десять лет с тех пор, как Джон Коннор помог предотвратить Судный День и спасти человечество от массового уничтожения. Теперь ему 25, Коннор не живет «как все» - у него нет дома, нет кредитных карт, нет сотового телефона и никакой работы. Его существование нигде не зарегистрировано. Он не может быть прослежен системой Skynet - высокоразвитой сетью машин, которые когда-то попробовали убить его и развязать войну против человечества. Пока из теней будущего не появляется T-X - Терминатрикс, самый сложный киборг-убийца Skynet. Посланная назад сквозь время, чтобы завершить работу, начатую её предшественником, T-1000, эта машина так же упорна, как прекрасен её человеческий облик. Теперь единственная надежда Коннору выжить - Терминатор, его таинственный прежний убийца. Вместе они должны одержать победу над новыми технологиями T-X и снова предотвратить Судный День...",
 "f-wd863963": "Это сказка о настоящей дружбе, о необыкновенных и очень опасных приключениях веселого лягушонка и его друзей, находчивость и смекалка которых помогают ему в самую трудную минуту.  В деревушке под названием Сонная Лощина поселяется необычный человек по имени Икабод Крэйн. Как-то раз ему рассказывают легенду о таинственном всаднике без головы, который обезглавливает свои жертвы…",
 "f-wd107724": "Четвертый фильм о Джеймсе Бонде, агенте английской секретной службы. Террористы из организации «Спектр» захватывают бомбардировщик с двумя атомными бомбами на борту и угрожают взорвать их, если британское правительство не доставит им алмазов на 100 миллионов фунтов стерлингов.",
 "f-wd223884": "Сюжет фильма основан на реальных событиях середины 90-х годов прошлого века, когда народ хуту, составлявшее в Руанде этническое большинство, устроило в стране кровавую резню, уничтожив более миллиона (!) человек, принадлежавших народу тутси.Главный герой фильма по имени Пол — управляющий престижного отеля в столице Руанды, в котором от убийц укрылись несколько сотен человек. Пол делает все от него зависящее, чтобы их спасти. Ситуация осложняется тем, что жена Пола также принадлежит народу тутси. У Пола большие связи, он не гнушается ни подкупом, ни шантажом; он угрожает, умоляет, льстит… И спасает от гибели 1268 человек.",
 "f-wd272064": "Чтобы остановить двойного агента, продажного сотрудника КГБ, бывшего генерала советских войск, снабжающего оружием террориста и наркобарона в Афганистане, агент 007 будет следовать за ним и побывает в скалах Гибралтара, в Чехословацком концертном зале, в Танжере и даже в той части Афганистана, где вовсю идут бои.",
 "f-wd62665": "В 1930-е годы двое отпетых мошенников пытаются отомстить главарю мафии за смерть их общего друга с помощью одной из самых неожиданных афер в истории кино, которая к тому же заканчивается удивительным и забавным образом.",
 "f-wd25167044": "На этот раз Ральф и Ванилопа фон Кекс выйдут за пределы зала игровых автоматов и отправятся покорять бескрайние просторы Интернета, который может и не выдержать сокрушительного обаяния громилы.",
 "f-wd2201": "Главный герой — школьник Дэйв Лизевски, который, вырядившись в костюм супергероя, пытается бороться с преступниками, хотя не обладает для этого никакими способностями. Параллельно два персонажа — 11-летняя девочка, которая крошит гангстеров мечом и сынок гангстера, ведущий собственное расследование, пытаются выяснить личность Дэйва…",
 "f-wd192979": "Воспитанный человеком сын Бога Персей не смог защитить свою семью от Аида, мстительного повелителя подземного мира. Теперь ему уже нечего терять, и он соглашается возглавить опасную миссию, чтобы одержать победу над Аидом и не позволить ему отобрать власть у Зевса и выпустить демонов подземного царства на Землю.\r Возглавляя отряд бесстрашных воинов, Персей отправляется в рискованное путешествие по лабиринту запретных миров. Чтобы победить в свирепой схватке с жуткими демонами и злобными чудовищами, противостоять злому року и стать хозяином своей судьбы, он должен осознать и принять свою божественную силу.",
 "f-wd156597": "«Люди в черном 2» продолжает рассказ о приключениях двух элитных полицейских — агента Кея и агента Джея среди инопланетян. Со времени их предыдущих похождений прошло четыре года.Все эти годы агент Кей вел размеренный образ жизни, в то время как агент Джей продолжал бесстрашно трудиться в рядах самой секретной организации в мире. Расследуя самое обычное дело, агент Джей натыкается на следы дьявольски изощренного заговора, задуманного Серлиной, злобным монстром, обитающим на Земле в образе сексуальнейшей модели.",
 "f-wd463101": "В конце шестидесятых дикие сердцем отправлялись в Вудсток, неудачники — на войну, а те, кому отправиться было некуда, — в бездну. После того, как Сюзанне поставили диагноз «пограничное состояние», девушка оказывается в закрытом психиатрическом учреждении, и чтобы подняться со дна пропасти к свету, она должна победить хаос в самой себе и в окружающем мире. Но так трудно сражаться с бесплотным врагом, особенно если это твоя собственная тень…",
 "f-wd469624": "Будущее. 2029 год. На гигантской космической станции астронавт Лео Дэвидсон обучает обезьян управлять летательными аппаратами. Неожиданно один из его учеников теряет контроль над космолетом и его уносит в еще не изученную область пространственно-временных туннелей. Не раздумывая ни секунды Лео бросается на выручку шимпанзе, но его постигает та же участь. Пройдя сквозь туннель, он совершает скачок во времени и попадает на неизвестную планету, где цивилизация воинствующих обезьян превратила Людей в своих рабов. Оказавшись в плену у обезьян, Лео пытается отстоять права человечества на свободу. Но как могут вооруженные палками люди сопротивляться закованным в доспехи злобным гориллам-убийцам? Единственный шанс выжить и победить в этой битве, это добраться до скрывающей страшную тайну происхождения обезьян Запретной зоны.",
 "f-wd41754": "Как только на город спускается ночь, в ущельях улиц раздается рев мощного мотора, и все в ужасе пытаются скрыться, заслышав этот звук. Ведь он возвещает приближение Призрачного Ездока - жуткого демона мщения с пылающим черепом вместо головы, рассекающего на объятом адским пламенем черном мотоцикле. И никто не знает, что под ужасной личиной палача из преисподней кроется трюкач и каскадер Джонни Блэйз, заключивший сделку с Мефистофелем. Согласно договору, днем он - обычный человек. Однако ночью герой превращается в могучего духа, отправляющего в геенну негодяев, ушедших от правосудия. Но даже Призрачному Ездоку понадобится дополнительная дьявольская мощь, когда ему придется сразиться с мегазлодеем по имени Черное Сердце - восставшим против отца сыном Сатаны, мечтающим создать новый ад, по сравнению с которым старый покажется раем!..",
 "f-wd303678": "Приключения троицы непоседливых братьев-бурундуков продолжаются! Элвин, Саймон и Теодор, а также их подруги бурундушки, просто не могут оставаться в стороне от различного рода неприятностей, сулящих им новые увлекательные приключения. Что на этот раз уготовила судьба нашим героям, и как они выпутаются из очередной передряги — вот в чём вопрос.",
 "f-wd496266": "Очаровательная американка Регги Ламберт, подав на развод, уезжает на курорт, где знакомится с привлекательным незнакомцем Питером Джошуа. По возвращению в Париж ее ждет ужасная новость: ее муж убит при загадочных обстоятельствах, а все семейные сбережения были сняты с банковского счета и исчезли в неизвестном направлении… И вот в жизни героини во второй раз (случайно ли?) появляется ее недавний знакомый под другим именем, а за ним — целая толпа «однополчан» ее покойного супруга, жаждущих заполучить кругленькую сумму, которую ее благоверный украл во время Второй Мировой Войны. Все ее преследователи уверены, что она-то уж точно знает о местонахождении злосчастного наследства.  По мере того, как охотники за «военным трофеем» начинают погибать один за другим, Регине становится все сложней разобраться, кому она может доверять.",
 "f-wd60487": "В заключительной главе этой легендарной саги Белла и Эдвард вступают в судьбоносное сражение с Вольтури из-за новорожденной дочери.",
 "f-wd464014": "Она владеет всеми видами рукопашного боя, стреляет из любых видов оружия и способна выжить в самых экстремальных условиях. Эта девушка - дочь лорда, леди Лара Крофт. Однажды под лестницей она обнаруживает вход в секретную комнату, где находятся старинные часы с удивительным устройством внутри.",
 "f-wd28561715": "Жизнь джек-рассел-терьера Макса переворачивается, когда у его любимой хозяйки рождается сын. Оказывается, забота о ребёнке — это большой стресс даже для самого отважного пса.",
 "f-wd681918": "В Сюзан Мёрфи, девушку из Калифорнии, прямо в день ее свадьбы попадает метеорит, полный всякой дряни из космоса, в результате чего она вдруг начинает расти и вырастает до пятнадцати метров. Встревоженные появлением нового монстра, военные сразу берутся за дело: Сюзан отлавливают и увозят на секретную правительственную базу.",
 "f-wd2235380": "Поэтическая кинопритча Сергея Параджанова об армянском поэте Саят-Нова, в которой единой сюжетной линией показан духовный мир Поэта, история его любви, отношение Поэта к религии, светской власти, народу. При отсутствии обычного литературного монолога все решения автора фильма лежат в чисто изобразительной сфере.",
 "f-wd964657": "Фильм расскажет про американскую туристку, оказавшуюся вместе со своими согражданами в Москве в момент нападения инопланетян на столицу России.",
 "f-wd1807931": "1920 год. Английские войска оккупируют Монголию. В руки бедного охотника попадает древняя грамота, свидетельствующая, что ее обладатель - потомок великого завоевателя Чингиз-хана. Англичане объявляют его принцем, рассчитывая использовать как марионетку в политической игре.",
 "f-wd48416710": "Фильм рассказывает о самом начале творческого пути Виктора Цоя и группы «Кино», о его взаимоотношениях с Майком Науменко, его женой Натальей и многими, кто был в авангарде рок-движения Ленинграда 1981 года. Это история о Ленинграде 80-х, о любви, поисках и больших надеждах — о настроении, которое останется с нами навсегда.",
 "f-wd55655546": "Падение инопланетного объекта разделило жизни на «до» и «после». Обычная девушка из московского Чертанова — Юлия Лебедева — вынуждена смириться с ролью подопытного кролика в лаборатории. Ведь она единственная была в контакте с пришельцем. Учёные и военные разбирают на атомы её чувства, эмоции и переживания, пытаясь разгадать природу растущей в ней силы. Но страшнее всего, что её сверхъестественные способности волнуют не только землян. Над планетой в буквальном смысле нависла угроза вторжения. И победить в грядущем столкновении можно только одним способом: найти в себе силы остаться людьми. Когда каждый ради общего спасения должен сделать выбор, от которого зависит жизнь и судьба миллионов, — смогут ли любовь, верность и милосердие стать сильнее безжалостной силы и инопланетных технологий?",
 "f-wd873313": "Об участии венгерских красногвардейцев в гражданской войне в России. Разбит один из венгерских отрядов. Молодому бойцу Ласло удаётся бежать в монастырь, где расположились венгры. Но врывается отряд белых и расстреливает борцов за революцию. Однако татарину Чингизу, венграм Ласло и Андрашу, а также русскому матросу удаётся вырваться за пределы города...",
 "f-wd4157228": "Киноальманах по новеллам О’Генри: «Дороги, которые мы выбираем», «Родственные души», «Вождь краснокожих». Трагикомические истории о незадачливых предпринимателях. Герои каждой отдельной новеллы пытаются поправить свои дела, но всякий раз попадают в непредвиденную ситуацию, которая сводит на нет все их усилия...",
 "f-wd28180653": "После аварии молодой талантливый архитектор приходит в себя в очень странном мире, лишь частично похожем на реальность. Ему предстоит выяснить, по каким законам существует это пространство, бороться за жизнь, встретить любовь, найти, наконец, выход в реальный мир и осознать его по-новому, поняв, что такое КОМА на самом деле.",
 "f-wd177145": "История дружбы между маленьким деревенским мальчишкой и старым рыбаком. Сантьяго, сильный и гордый человек, он не может смириться с неумолимым течением времени, отнимающем физические силы.  Уже много недель он возвращается с моря без улова. Наконец он принимает решение — уйти за добычей далеко-далеко в море и без улова не возвращаться. Только так старый рыбак может вернуть себе уверенность и самоуважение.  Рано утром он прощается со своим маленьким другом, с родным берегом, который видит, возможно, в последний раз, и растворяется в темноте морских вод. И все же удача приходит к рыбаку. В его снасти попадается гигантская рыба.  Двое суток в море продолжается их поединок, но рыба не сдается и тянет Сантьяго все дальше и дальше в море. Но старый рыбак убедил себя в том, что упорство и сила духа — это то, что принесет ему победу…",
 "f-wd1198723": "Документально-публицистический фильм, разоблачающий человеконенавистническую сущность фашизма, показывающий ту почву, на которой он был взращен. В картине были использованы трофейные хроникальные материалы из киноархивов министерства пропаганды нацистской Германии и личного фотоархива Гитлера, а также многочисленные любительские снимки, обнаруженные у эсэсовцев.",
 "f-wd3228251": "Первый советский научно-фантастический фильм о покорении космоса. Научная сторона фильма была почти безупречной. Кроме устаревших деталей (старт с эстакады, противоперегрузочные ванны), все остальное впечатляет и сегодня. Во многом благодаря тому, что консультировал создателей ленты сам Константин Эдуардович Циолковский.",
 "f-wd261240": "Более ста лет загадка земли, затерянной среди арктических льдов, волновала путешественников, но никто не мог достичь её. Герой фильма, политический ссыльный Ильин, отправляется в экспедицию, которую финансирует богатый золотопромышленник. Отважные путешественники обнаруживают среди ледяного безмолвия цветущий оазис. Но выясняется, что во время землетрясения он должен исчезнуть. Ильин с товарищами стремится снова достичь материка в попытке предотвратить катастрофу...",
 "f-wd651553": "Фильм рассказывает о простой ленинградской девушке начала 30-х годов — вчерашняя студентка оказывается в далёкой алтайской деревне, где сталкивается с чужой, незнакомой и пугающей её реальностью.",
 "f-wd2406650": "Экранизация пьесы Уильяма Шекспира. Сюжет построен на истории легендарного короля Лира, который на склоне лет решает удалиться от дел и разделить своё королевство между тремя дочерьми. Для определения размеров их частей он просит каждую из них сказать, как сильно она его любит. Две старшие дочери используют этот шанс, а младшая - Корделия - отказывается льстить, говоря, что её любовь выше этого. Разгневанный отец отрекается от младшей дочери. Лир делит королевство между старшей и средней дочерьми.  Однако вскоре, после ужасного приёма, оказанного ему ими, он понимает, сколь лицемерно расчётливы были его старшие дочери со своей показной «любовью». Напряжение в отношении дочерей к королю обостряет политическую ситуацию в королевстве, которое готово вот-вот исчезнуть.",
 "f-wd1976473": "Бывший гимназист Валерка, весёлый отчаянный Яшка-цыган, оставшиеся сиротами Данька и его сестрёнка Ксанка дали клятву внедриться в отряд к атаману Бурнашу и отомстить ему и его банде за смерть отца Даньки. Под видом сына старого друга атамана Данька проникает в отряд Бурнаша. Однако бандиты сумели узнать об этом. Даньку ждёт казнь, но друзья на то и друзья, чтобы не бросить своего товарища в беде.",
 "f-wd4243413": "Начинающий диджей Толик и всемирно известный виолончелист Владимир Чижов встречают на шумной московской улице босого человека. Нажав на кнопку странной машинки, герои перемещаются на пустынную планету Плюк. Анимационный ремейк любимого всеми фильма «Кин-дза-дза!» не менее увлекательно и смешно, чем оригинал, рассказывает о приключениях Толика и дяди Вовы. В этом мире песка жители делятся на две категории — пацаков и чатлан, простая спичка обладает невероятной ценностью, а людей встречают и провожают по цвету штанов.",
 "f-wd4083077": "Горный инженер Смит воспитывает собаку, которую он спас во время кровавого собачьего боя. Но его питомец Белый Клык злобен и агрессивен, ведь его воспитывали как пса-убийцу.  Не мало прошло времени, прежде чем человек и собака подружились. Но однажды ночью за Клыком пришел его прежний хозяин, вооруженный револьвером.",
 "f-wd4315419": "Фильм состоит из трёх новелл, снятых по произведениям Михаила Зощенко (комедии «Преступление и наказание», рассказу «Забавное приключение» и пьесе «Свадьба») и объединённых темой мещанской «любви».",
 "f-wd4146327": "Сталинградская битва - начало коренного перелома в ходе Великой Отечественной войны. Танковой армаде фашистских войск, спешащей на выручку окружённой группировке фельдмаршала Паулюса, противостоит армия генерала Бессонова. Основной удар приняла на себя артиллерийская батарея комбата Дроздовского, состоящая из недавних выпускников военных училищ, ещё не обстрелянных в боях. После жестокого сражения от батареи осталось одно орудие и несколько полуживых бойцов. Но враг не прошёл.",
 "f-wd4163531": "Действие фильма происходит в пионерском лагере. Пионер Костя Иночкин переплыл реку и оказался на запретной для посещений территории, за что и был изгнан его начальником товарищем Дыниным. Не желая доводить бабушку до инфаркта своим досрочным прибытием, мальчик тайно возвращается в лагерь, где пионеры также тайно содержат его и предпринимают все меры, чтобы не состоялся родительский день.",
 "f-wd60173312": "Могущественный король Харальд чуть не потерял семью из-за Снежной королевы. Он находит способ очистить мир от волшебства — все обладатели магических способностей отныне заточены в Зазеркалье. Остановить его и не дать сказке навсегда исчезнуть из нашего мира может только Герда. Ведь её главная сила не в волшебстве, а вере в добро и дружбу. В новом приключении на помощь Герде придут тролли, пираты и даже сама Снежная королева.",
 "f-wd3053554": "Экранизация одноименного автобиографического романа М. Горького, второй части известной автобиографической трилогии писателя Алеша Пешков уходит из дома своего деда и отправляется на заработки, «в люди». Служит «мальчиком» у дяди-чертежника, мойщиком посуды на волжском пароходе, учеником в иконописной мастерской. Добрый, чуждый жестокости, он не может вынести царящей кругом несправедливости, отважно борется за правду и вновь оказывается без угла и куска хлеба.",
 "f-wd4315518": "Три друга, лётчики-офицеры, поклялись не любить до конца войны. Однако военная служба познакомила из с лётчицами женской эскадрильи. И друзья один за другим начали сдавать свои позиции. После тяжёлого ранения лётчик Булочкин вынужден летать не на скоростном истребителе, а на «тихоходе» У-2. Привыкший к опасностям Булочкин с трудом привыкает к спокойной жизни в эскадрилье, где большинство лётчиков — девушки. Но вскоре становится ясно, что на войне важны и «тихоходы».",
 "f-wd4406483": "У инженера Нади Клюевой максимум общественной, но минимум личной жизни. Всё меняется, когда она случайно встречает в автобусе свою старую знакомую, школьную одноклассницу Сусанну, ныне работающую социологом на заводе бытовых кондиционеров. Сусанна решает наладить личную жизнь своей подруги, используя научный метод.",
 "f-wd4285422": "На заре XX века все так же беспросветна жизнь простой русской женщины Пелагеи Ниловны Власовой, жены чернорабочего-пропойцы. Неожиданная смерть главы семьи, кажется, не сулит ей никаких надежд, но, видя слезы матери, молодой Павел Власов отказывается от разгульной жизни. Увлекшись пролетарскими идеями, он распространяет листовки на фабрике и призывает рабочих бороться с угнетателями. Смелое преображение сына воодушевляет и саму Ниловну: робкая, страшащаяся людей женщина преисполняется гордости и самоуважения. Но хватит ли матери мужества продолжить дело своего единственного сына?",
 "f-wd126086662": "Начало XX века. Лесоруб и железнодорожник Роберт Грейниер проводит многие месяцы вдали от дома на работе: он валит лес, укладывает шпалы и помогает строить мосты. Он становится свидетелем не только того, как жизнь и страна вокруг него меняются, но и того, какой ценой даются эти изменения простым рабочим и трудовым мигрантам.",
 "f-wd886645": "Инспектор Сильвестр берется за расследование жестокого убийства модели Изабеллы, которое совершил неизвестный в маске. С ходом расследования на поверхность всплывают скрываемые за закрытыми дверьми модного дома грехи. Скоро выясняется, что Изабелла вела дневник, в котором хранила все эти секреты. Обстановка начинает накаляться до критических пределов.",
 "f-wd28956599": "Армейский священник Толлер, оплакивающий гибель сына-солдата, ищет утешения под сводами церкви. Здесь он знакомится с молодой прихожанкой Мэри, женой рьяного защитника природы. Когда эколог-активист кончает жизнь самоубийством, Толлер и несчастная вдова открывают правду о коррупционном заговоре, в котором замешены самые почтенные лица, включая священнослужителей.",
 "f-wd850312": "31 октября 1975 года. По городу проносится волна кровавых убийств. Жители шёпотом произносят имя Майкла Майерса, кровавого маньяка, который вернулся как раз на Хэллоуин. Его прежняя жертва, Лори Строуд, выжила, и он вернулся, чтобы закончить начатое. На сей раз преследования Лори приводят его в больницу, и в её темных коридорах хладнокровный неубиваемый психопат находит свои жертвы.",
 "f-wd23755403": "Когда сестра героя, генеральный директор компании, угрожает брату закрыть его филиал, он устраивает эпическую рождественскую вечеринку, чтобы заполучить большого клиента и спасти фирму. Однако праздник выходит из-под контроля..",
 "f-wd1127828": "«Koyaanisqatsi» — с языка индейцев племени хопи — это безумная жизнь, беспорядочная жизнь, жизнь на грани распада, жизнь вне баланса, жизнь, требующая изменений во имя продолжения жизни…\r \"Коянискацци\" (Koyaanisqatsi; Жизнь, выведенная из равновесия) - документальный фильм Годфри Реджио с музыкой композитора-минималиста Филипа Гласса и киносъёмками Рона Фрика. Лента содержит большое количество фрагментов, снятых по технологии замедленной киносъёмки. Фильм полностью лишён дикторского текста и актёрской речи, однако его музыкальное оформление, на которое опирается сюжет, занимает в повествовании такое же значение, как и видеоряд, и, фактически, создаёт атмосферу фильма. Это первый из трилогии фильмов \"Кацци\", показывающей с различных сторон взаимодействие человека и технологии. Более десятилетия из-за лицензионных ограничений фильм \"Коянискацци\" не издавался, так как Филип Гласс и его ансамбль гастролировали с ним, вживую исполняя музыку прямо перед киноэкраном во время показов.",
 "f-wd39571": "Сестры Сацуки и Мэй переезжают вместе с папой в деревенский дом. Однажды девочки обнаруживают, что по соседству с ними живут лесные духи — хранители леса во главе со своим могущественным и добрым повелителем Тоторо. Постепенно Тоторо становится другом девочек, помогая им в их повседневных приключениях.",
 "f-wd120237363": "Как и предсказывал Кевин Флинн, стало возможным перемещение предметов и человекоподобных программ из виртуального мира в реальный. Джулиан Диллинджер, глава компании Dillinger Systems, привлекает инвесторов демонстрацией невероятных возможностей новой технологии, не упоминая, что в нашем мире воссозданные объекты могут существовать только 29 минут. А тем временем руководительница ENCOM Ева Ким находит так называемый код устойчивости — программу, которая снимает это ограничение по времени. Узнав об успехе конкурентов, Джулиан приказывает поймать Еву и забрать у неё ценный код своим лучшим солдатам — извлечённым из виртуального мира ИИ по имени Арес и Афина.",
 "f-wd127163221": "Маньяк преследует и убивает влюбленных в День святого Валентина.",
 "f-wd5966063": "История матери, которая сталкивается с паранормальными явлениями в своем старом доме. Спустя 30 лет после инцидента, она возвращается в этот дом, чтобы разгадать тайну этих событий…",
 "f-wd21451640": "Когда бывший коллега Джона решает взять под свой контроль таинственную гильдию убийц, Уик вынужден выйти из отставки. Ведомый кровавой клятвой Джон отправляется в Рим, где ему придется сразиться с одними из самых опасных киллеров в мире.",
 "f-wd22074949": "Продолжение истории о Вилли — пьянице, бабнике, уголовнике и воре, который, чтобы заработать легких денег, переодевается в канун Рождества в Санта-Клауса. В этом костюме ограбить очередной супермаркет не представляет никаких проблем. Но в Рождество случаются всякие чудеса. Каким оно будет для Вилли в этот раз?",
 "f-wd35083659": "Молодой москвич Кирилл — талантливый дизайнер компьютерных игр. В один прекрасный день он оказывается напрочь стертым из памяти всех, кого он знал и любил. Кирилл узнает, что выбран для важной и таинственной миссии. Его предназначение — стать таможенником между параллельными мирами, коих во Вселенной десятки. Сможет ли Кирилл разгадать тайну этих таинственных миров и того, кто и зачем ими управляет? И действительно ли наша Земля — всего лишь воображаемый «черновик», параллельный мир, которого в Реальности не существует…",
 "f-wd16997069": "В новой главе антиутопии об обществе, где все расставлено по полочкам, а любая индивидуальность подлежит искоренению, Трис должна найти способ борьбы со страшной системой, уничтожающей ее близких. Кто из них на очереди? Она узнает все больше страшных подробностей, стоящих за кажущимся порядком, и уже не может не видеть, что в ее мире пора что-то менять. Но главное в этой борьбе — справиться с расколом, который враг порождает в ее собственной душе.",
 "f-wd114707487": "Легенде кунг-фу По предстоит найти преемника и обучить нового Воина Дракона. Однако планы панды нарушает злая колдунья и пытается вернуть из мира духов злодеев, которых уже одолел По.",
 "f-wd207659": "Мультмонстры с планеты \"Гора придурков\" вторгаются на Землю, желая захватить персонажей популярного сериала \"Луни Тюнз\". Земные зверюшки во главе с кроликом Багзом Банни предлагают на спор сыграть в баскетбол, привлекая на свою сторону суперзвезду Майкла Джордана.",
 "f-wd14370516": "Барни, Кристмас и остальные члены команды сходятся лицом к лицу с Конрадом Стоунбэнксом, многие годы назад основавшем вместе с Барни команду «Неудержимых». Впоследствии Стоунбэнкс становится безжалостным торговцем оружием, и тем самым превращается в человека, которого Барни было поручено убить... Или, по крайней мере, он сам так считал. Теперь Стоунбэнкс, один раз уже сумевший обмануть смерть, поставил себе цель покончить с «Неудержимыми» - но у Барни на этот счёт свои планы. Барни решает, что в его борьбе «свежий» подход можно противопоставить старым методам, и пополняет ряды людьми, которые моложе, быстрее и технически более подкованные. Так у членов команды «Неудержимых» начинается новая эра. Последняя миссия превращается в столкновение между представителями классической «старой школы» и экспертами в высоких технологиях.",
 "f-wd327713": "Агент Джей узнает, что никакого защитного галактического щита, способного отразить иноземный удар, не существует. Агент Кей не построил его, потому что был убит в 1969 году. Агент Джей должен совершить путешествие во времени, чтобы спасти Землю и жизнь напарника.",
 "f-wd3222190": "Бродяга Франк Морис случайно забредает на стоящую в стороне от оживлённой трассы бензоколонку и честно признаётся её хозяину Нику Морино, что он голоден и что у него ни гроша. Хозяин щедро угощает его, а затем предлагает работать в ночную смену. Франк, не привыкший работать, хочет отказаться, но замечает за барной стойкой жену хозяина — красавицу Кору.",
 "f-wd156069": "Мир охвачен смертельной эпидемией, превратившей большую часть человечества в кровожадных зомби. Элис вместе с группой выживших пересекает опустошённые земли в поисках безопасного места, сталкиваясь с бандами мародёров, заражёнными и другими опасностями. Тем временем корпорация «Амбрелла» продолжает эксперименты с вирусом и пытается создать совершенное биологическое оружие. Когда пути Элис и корпорации вновь пересекаются, ей приходится вступить в борьбу с силами, которые стремятся использовать её необычные способности в своих целях.",
 "f-wd685785": "Человек создал искусственный разум, но не смог дать механизму душу. И однажды его творение подняло руку на своего создателя…В страшной войне человечество было уничтожено механическими монстрами. Перед тем как погибнуть, профессор, придумавший умные машины, сшил девять тряпичных кукол, вложив в них человеческие души. Девять Героев. Девять Характеров. Только вместе, помогая друг другу, им суждено выжить. Выжить, чтобы выполнить свою миссию… возродить на Земле жизнь.Теперь наш огромный мир в их маленьких руках.",
 "f-wd23068002": "Томас возглавляет отряд выживших глейдеров, чтобы выполнить последнюю и самую опасную миссию. Ради спасения своих друзей они должны проникнуть в легендарный Последний город, смертоносный лабиринт, контролируемый ПОРОКом. Каждый, кто выживет там, наконец-то получит ответы на все вопросы, которые мучили глейдеров с момента попадания в лабиринт.",
 "f-wd181803": "В заключительном шестом эпизоде «Звездных войн» Дарт Вейдер создает вторую «Звезду Смерти». Он объединяет все силы зла, чтобы с помощью этого смертоносного оружия нанести последний сокрушительный удар по повстанцам и их союзникам. Люк Скайуокер вместе с принцессой Лейей и верными дроидами R2D2 и C-3PO отправляется спасать своего друга Хана Соло, который попал в плен к отвратительному Джаббе Хатту — могущественному повелителю преступников.",
 "f-wd21203766": "Действие фильма переносит зрителя в 70-е года прошлого века. Главный герой организует экспедицию к Острову Черепа, вечно покрытого туманом, на котором когда-то был пойман Кинг-Конг, чтобы найти пропавшего брата и некую таинственную субстанцию. Во время нелегких поисков путешественникам предстоит столкнуться с кошмарным миром монстров жуткого острова.",
 "f-wd657977": "Экранизируя роман маркиза де Сада, Пазолини переносит действие в 1944-45-е годы, в фашистскую «республику Сало» на севере Италии, где группа лиц из высшего общества во главе с принцем унижает, издевается, мучает, пытает юношей и девушек, собранных для услаждения извращённой элиты, чувствующей свою погибель. Четыре месяца длится эта экзекуция. Для взрослых это последняя возможность удовлетворить свои низменные инстинкты, для молодых людей — расплата за свою юность и желание жить.",
 "f-wd639481": "Фильм рассказывает истинную историю странной и пестрой жизни самой одиозной фигуры американского кино — Эда Вуда, признанного худшим режиссером за всю историю Голливуда!",
 "f-wd223367": "Кинотрактовка закулисных взаимоотношений английской королевы Елизаветы II и премьер-министра Тони Блэра, развивающихся на фоне многочисленных проблем, возникших в связи с трагической гибелью принцессы Дианы. Август 1997 года. Любимица Соединенного Королевства принцесса Диана погибла в автокатастрофе. Королева Елизавета II, несмотря на все ожидания британского общества, уединяется в замке Балморал, где пытается осознать весь масштаб постигшей Великобританию утраты.Однако недавно избранный премьер-министр Тони Блэр понимает, что сложившаяся ситуация может отвернуть простых британцев от престола. Поэтому на его плечи ложится весь груз ответственности по поиску компромисса между глубоко личной трагедией королевского дома и желанием общественности увидеть ее публичные проявления.",
 "f-wd497311": "В институт психиатрии приезжает новый директор, известный ученый Эдвардс. Сотрудница института Констанс Питерсен проявляет к нему не только профессиональный интерес, и у них завязывается бурный любовный роман.  Но молодой профессор начинает вести себя очень странно, и вскоре Констанс обнаруживает, что ее возлюбленный не тот, за кого себя выдает — он самозванец, страдающий амнезией. Его настоящее имя Джон Баллантайн, и все указывает на то, что он был пациентом пропавшего доктора Эдвардса и, возможно, он и есть убийца.  Не веря, что Джон преступник, Констанс увозит его к своему старому учителю доктору Брюлову. Они надеются, изучив сны Джона, раскрыть тайны, скрытые в безднах его сознания.",
 "f-wd7820305": "Связанные общей судьбой, талантливая девушка-подросток с невероятной тягой к новым знаниям и бывший гений-изобретатель, переживший разочарования и крах своих иллюзий, отправляются сквозь пространство и время в полную опасностей миссию, чтобы раскрыть секреты таинственного места, которое существует в их общей памяти под названием «Земля завтрашнего дня».",
 "f-wd725946": "Фрэнк Фармер, сотрудник службы безопасности президента Рейгана, чувствует себя отчасти виновным в том, что в его отсутствие на президента было совершено покушение. Он покидает службу и за большой гонорар, но всё же нехотя, нанимается телохранителем чернокожей певицы и актрисы Рэйчел Мэррон, которая постоянно получает письма с угрозами. Первоначальная антипатия, возникшая между ними, постепенно перерастает в любовь. Сложившаяся ситуация мешает телохранителю исполнять свой профессиональный долг, что приводит к частым конфликтам между Фрэнком и Рэйчел... Фармер приходит к выводу, что угроза жизни Рэйчел исходит отнюдь не от психопата, а от профессионального убийцы.",
 "f-wd11640531": "Братья Тим и Тед давно повзрослели и отдалились друг от друга. Тед стал генеральным директором инвестиционного фонда, а Тим посвятил себя семье. Он женился, поселился в пригороде и обзавелся двумя прекрасными дочерьми — Тиной и Табитой. 7-летняя Табита — умная и очень усердная. Несмотря на свой юный возраст, она уже лучшая в классе, а малышка Тина на самом деле оказывается агентом компании BabyCorp. Узнав, что злой гений доктор Эрвин Армстронг выращивает целую армию злобных малышей, Тина с помощью своего папы и дяди решает противостоять ему.",
 "f-wd1048958": "Стюарт - маленький белый мышонок, которого семья Литтлов решает усыновить, несмотря на удивление их сына Джорджа. В новом доме Стюарт быстро становится полноправным членом семьи, но не все готовы принять его с радостью. Домашний кот Снежок воспринимает мышонка как соперника и вместе с уличными котами пытается избавиться от него. Стюарту предстоит доказать, что настоящая семья определяется не внешностью и происхождением, а любовью, доверием и готовностью всегда быть рядом.",
 "f-wd22078002": "История о создании фильма «Комната» (2003), широко известного как эталон бездарного кино. Начинающий актер-красавец Грэг на актерских курсах знакомится с эксцентричным Томми Вайсо. У новых друзей совсем немного общего, кроме любви к актерству и желания самовыражаться, поэтому парочка отправляется покорять Голливуд.",
 "f-wd1166180": "Джулия и Лиллиан — подруги детства. Джулия родом из богатой еврейской семьи, воспитывалась в США у бабушки и дедушки. Между девочками были близкие отношения, но позже жизнь разлучила их. Увлеченная литературой Лиллиан сближается с Дэшилом Хэмметом, а студентка-медик Джулия отправляется в Европу, где вливается в антифашистское движение.",
 "f-wd29413154": "1998 год, Нальчик. Илана — девочка-подросток из хорошей семьи, которая всё делает наоборот. Перечит матери. Спорит с отцом. Чинит машины в автомастерской, не вылезая из спецодежды. Встречается с парнем, который не нравится её родителям. Пацанка и красавица, она идёт своим путём и жаждет свободы, но когда в доме происходит страшная трагедия, именно Илана оказывается единственной, кто способен спасти семью. Однако какой ценой?",
 "f-wd4993635": "Фильм становится первым документальным представителем одного из самых важных перестроечных жанров: \"проблемного\" фильма о молодежи. На смену давно устаревшим лозунгам пришло время судьбоносных вопросов — \"кто виноват?\", \"что делать?\" и сакраментального \"кому на Руси жить хорошо?\". Наступает период поиска ответов на эти \"вечные вопросы\" и искательного заглядывания в глаза новому поколению.",
 "f-wd1986362": "В последнюю зимнюю ночь 1953 года московский истопник Федя Арамышев по дороге на работу соблазняется блестящей фигуркой на радиаторе пустого, засыпанного снегом «Опеля», стоящего на обочине. Откуда было знать бедному Феде, что из-за легкомысленного поступка он попадет в историю, связанную «делом врачей», оперативными планами МГБ и высокой политики. Эта история так и останется для него неизвестной, он так и не поймет из-за чего получил десять лет лагерей...",
 "f-wd50961": "Фильм-опера по одноименному роману в стихах А. С. Пушкина и опере П. И. Чайковского. Болезнь дядюшки вынуждает дворянина Евгения Онегина покинуть Петербург и отправиться к одру больного…",
 "f-wd4212459": "Заболевший дядя Фёдор был увезён в первом мультфильме родителями в город, а заблудшая на участок корова стала давать огромное количество молока. Шарик и кот Матроскин вяло поругивались, но жили в целом мирно. А тем временем мама решила поехать на курорт, чтобы износить четыре вечерних платья, а на вокзале дядя Фёдор сбежал и укатил в Простоквашино к своим старым друзьям. Шарику прислали фоторужьё, Корова родила телёнка, которого Шарик учил служить. Много было весёлых и славных событий, а под конец и мама приехала с папой. Если бы у неё была вторая жизнь, она бы её провела в Простоквашино.",
 "f-wd4198676": "Двое случайных знакомых узнают о том, что их супруги являются любовниками. Это открытие заставляет их совершать поступки, на которые они не решились бы ранее.Ревность или страсть, месть или прощение — герои ищут основы для новой жизни, но сделать это нелегко — измена подчиняет все их поступки своей логике.",
 "f-wd4341995": "Давненько когда-то, в одной весьма пластилиновой местности, жил да был орёл-мужчина, как-то под новый год послала его жена за ёлкой...",
 "f-wd133273688": "В 2006-ом году журналист и телеведущий Крис Хансен начинает работу над новым расследовательским шоу «Поймать хищника», в котором его команда с помощью скрытых камер разоблачает мужчин, пытающихся встретиться с несовершеннолетними через интернет. Под видом потенциальных жертв журналисты назначают встречи, после чего подозреваемых разоблачают перед камерами и передают полиции. Шоу быстро привлекает огромное внимание зрителей и превращается в телевизионную сенсацию, однако стремление раскрывать всё новые дела постепенно приводит Хансена и его команду к опасной грани между журналистским расследованием, телевидением и самосудом.",
 "f-wd152780": "Это история сына владельца одного индийского зоопарка, мальчика по имени Пи. Он познаёт мир, учится отстаивать свои принципы, ищет собственную дорогу к Богу, живя по канонам трёх конфессий, влюбляется… Но волей судьбы его семья вынуждена эмигрировать. На полпути между Индией и Канадой корабль терпит крушение, и Пи остаётся в шлюпке вместе с бенгальским тигром, гиеной, зеброй и орангутаном. Вокруг безбрежная водная гладь, а впереди — неизвестность…",
 "f-wd124246549": "Империя пала, но её военачальники всё ещё держат под своим контролем части галактики. Зарождающаяся Новая Республика пытается защитить идеалы, за которые сражались повстанцы, и нанимает для задания мандалорца Дина Джарина, известного охотника за головами, и его юного ученика Грогу.",
 "f-wd108552200": "Писатель Бен Мирс возвращается в родной городок и узнаёт, что в нём теперь обитают вампиры.",
 "f-wd23999306": "Знаете ли вы, что внутри каждого смартфона есть красочный городок Текстополис, в котором живут эмоджи? И что они ужасно радуются, когда владелец телефона именно их выбирает для своего сообщения? Каждый из эмоджи отвечает лишь за одну эмоцию, и только Джин может выражать несколько эмоций сразу. Он очень хочет стать таким же, как и его собратья, и для этого вместе со своими друзьями пускается в увлекательное путешествие по приложениям телефона в поисках программы, которая поможет ему измениться. Неожиданно герои узнают о грозной опасности, нависшей над городом. Смогут ли друзья спасти Текстополис и всех его обитателей?",
 "f-wd126683577": "Человечество узнаёт о прибытии на Землю инопланетян, чьё существование долгое время тщательно скрывалось.",
 "f-wd13897247": "Всё начинается со спасения ребенка, которого должны были убить солдаты, посланные правителем королевства Махишмати. Спустя годы мальчик превращается в крепкого и рослого юношу Шивуду. Однажды он находит маску и решает во что бы то ни стало разыскать её владельца, не подозревая, что она принадлежит прекрасной воительнице, которая всем своим кланом пытается вызволить из плена королеву Девасену, заточенную жестоким тираном Бхаллалой Девой.",
 "f-wd276299": "Действие картины проходит в середине 50-х годов, главные герои — члены небольшой провинциальной семьи. Фрэнк и Эйприл Уиллер считают себя семьей среднего класса, непохожей на остальные семьи, и испытывают огромное желание перебраться в Париж. Однако судьба приготовила для супругов ряд неприятных сюрпризов...",
 "f-wd105395068": "Недалекое будущее, 2040 год. Евгений и Александра 20 лет в браке, их отношения похожи на высохший урюк. Развестись у них тоже не получается, поскольку в будущем расторжение брака – очень дорогая услуга. Но судьба дает им шанс: Евгений и Александра попадают в прошлое, в тот самый день 20 лет назад, когда влюбленный и юный Женя сделал предложение прелестной Саше. Теперь пара из будущего хочет разлучить самих себя в молодости, но это будет непросто. Молодые будут сражаться за свою любовь.",
 "f-wd130368011": "Пятеро друзей становятся невольными виновниками автокатастрофы, в результате которой гибнет человек. Друзья принимают решение скрыть преступление и клянутся никогда не говорить о том, что произошло. Спустя год это трагическое событие напоминает о себе, когда таинственный убийца с крюком в руке пытается им отомстить. Чтобы остановить его, молодые люди обращаются за помощью к 2-ум выжившим после похожей резни в Саутпорте в 1997-ом году.",
 "f-wd108940313": "Обычный парень по имени Хануманту неожиданно получает способности Ханумана, одного из самых почитаемых индуистских божеств, известного своей безграничной силой. Он бегает со скоростью гепарда и с легкостью поднимает горы, чем удивляет не только себя, но и своих односельчан, которые теперь считают его супергероем. Пока парень учится жить со своей силой, неизвестный злодей сеет в городе хаос и держит всех в страхе. Он жаждет еще большей власти, и, чтобы ее получить, ему нужно использовать силу Хануманту.",
 "f-wd135319573": "Могущественный демон Хираньякашипу объявляет себя богом и решает уничтожить Вишну. Пытаясь восстановить равновесие, Вишну превращается в человека-льва Нарсимху и вступает в битву с демоном.",
 "f-wd122931571": "Путешествие супружеской пары принимает тревожный оборот, когда жена пропадает без вести, что побуждает мужа к отчаянным поискам, в то время как неизвестный злодей создает препятствия.",
 "f-wd123353613": "Маршал авиации, перевозящая преступника на маленьком самолете, оказывается в ловушке, когда подозревает, что их пилот не тот, за кого себя выдает.",
 "f-wd117323743": "Розочка узнаёт, что её возлюбленный Цветан когда-то был частью её любимого бойз-бэнда «Братаны» вместе со своими четырьмя братьями. Группа распалась, когда Цветан был ещё младенцем, и с тех пор он не видел своих братьев, но когда одного из них похищают неизвестные злодеи, Цветан и Розочка отправляются в путешествие, чтобы наконец-то воссоединить семью с помощью волшебной силы музыки.",
 "f-wd21001674": "Старый Каттаппа рассказывает Шиве, почему убил его отца Амарендру. После того, как тот был усыновлён королевой Сивагами, старший сводный брат Бхаллаладева всегда ему завидовал. Зависть достигла апогея после битвы с дикими племенами, когда Сивагами нарекла младшего сына наследником королевства. Бхаллаладева и его хитрый дядя начинают плести грязные интриги, чтобы сжить Амарендру со свету.",
 "f-wd136601804": "Индия, 1980-е годы. После того как муж оставляет Шазию Бано без финансовой поддержки и женится вновь, она решается бросить вызов устоявшимся традициям и системе, в которой голос женщины почти не слышен. Использование тройного талака становится не только личной трагедией, но и искрой, разжигающей масштабные общественные споры о справедливости, религии и правах женщин.",
 "f-wd573112": "Пронзительная история любви одного из самых знаменитых императоров Индии и прекрасной принцессы — эпическая сага времен XVI века. Джалалуддин Мохаммад Акбар (Акбар на арабском означает «великий »), оставивший след в истории как великий могол Акбар — мусульманин. Принцесса Раджпута, Джодха — индуистка. В то время, когда мусульмане и индуисты испытывали глубокую неприязнь друг к другу, их союз был призван не только соединить два сердца, но и две религии.",
 "f-wd603082": "Много лет назад в семью Аджая Шармы пришла беда. Компаньон его отца Чапра подделывает доверительные документы, в результате чего отец разоряется и, не пережив этого, умирает от инфаркта. Все эти годы юноша живет с мечтой отомстить преступнику. С этой целью он начинает встречаться со старшей дочерью Чапры..",
 "f-wd3500913": "Они молоды, амбициозны и еще не знают вкуса поражений. Но, когда-нибудь им придется столкнуться с настоящей взрослой жизнью, и почему бы не сделать это в новом учебном году, когда «проказник» декан дает возможность только одному из своих студентов стать лучшим из лучших, стать почетным студентом года. На фоне массового помешательства на учебе и спорте происходят и другие не менее важные события. Например, любимчик девушек Рохан Нанда сталкивается с соперником в лице скромного и серьезного Абхи Сингха. Но, если противостояние этих парней между собой со временем и переросло в крепкую дружбу, то что будет, когда в их мир внесет разлад любовь? Удастся ли первой красавице колледжа Шанайе случайно не разрушить эти отношения? Ведь теперь ее сердце, кажется, принадлежит не только одному из них…",
 "f-wd551343": "Наш фильм - это история женщины, которая борется за справедливость, вопреки всем невзгодам и вопреки самым богатым и могущественным членам общества... Главная героиня Шивани работает стюардессой в авиакомпании «ЭЙР ИНДИЯ» Она помолвлена с Ашоком - пилотом этой же авиакомпании. Однажды Шивани попадается на глаза богатому бизнесмену Виджаю Агнихотри, который вдруг стал стараться всеми силами женить Шивани на себе. Во что выльется каприз богача Вы узнаете из фильма, изобилующего самыми различными поворотами сюжета.",
 "f-wd1648332": "Молодой городской пижон Прем из Дели, выросший в богатом доме, возможно, подходящий холостяк, но он еще не готов к браку. Прем соглашается на встречу с сиротой Пунам из Мадхупура только из-за своего отца, который намерен женить сына. Но случилось чудо — формальное знакомство перерастает в любовь. Смогут ли молодые люди сохранить любовь или их будущий брак останется для них только символом повиновения?",
 "f-wd4692983": "Деревенский учитель Динанат Чаван, уважаемый человек, кроме прочих учеников, вынужден заниматься и с деревенской шлюхой. Злые завистники подстраивают так, что учителя застают во время урока с проституткой. Возмущенные жители деревни забивают учителя до смерти. Только его сын Виджай знает правду и решает отомстить за отца.",
 "f-wd2900709": "Головокружительную карьеру сделала бедная крестьянская девочка Уша. И с самого детстве ей всем помогал ей сосед Кешав. Небескорыстный Кешав мечтал, что когда Уша станет прославленной актрисой, он, женившись на ней, обеспечит себе безбедную старость.",
 "f-wd1058193": "Руп - фольклорный певец из штата пустынь Раджастхан, привозит своего отца Шамбху Ратхода в Бомбей на лечение, где и влюбляется в медсестру Пуджу, которая, по счастливому совпадению, без труда завоевывает сердце отца Рупа. Приехав в чужой город, Руп отправляется в ресторан, где прислуживает его земляк, и тут, на беду попадается на глаза сестре хозяина отеля Аджая Наранга - Решме. Не подозревая по простоте душевной о зародившейся страсти в душе Решмы, Руп с радостью соглашается работать певцом в ресторане при отеле ее брата.",
 "f-wd320574": "В фильме рассказывается история бенгальского таксиста. Пытаясь открыть свой бизнес, он оказывается вовлечённым в контрабанду опиумом. В фильме затронуты многие морально-этические проблемы, в частности веротерпимость и пережитки кастовой системы Индии.",
 "f-wd3342447": "Джессика, модель, ставшая барменшей, отказалась во внеурочное время подать спиртное Манишу, сыну высокопоставленного политического деятеля, и он застрелил её из пистолета. В зале ресторана в то время находилось около 300 человек, но ни один из них не решился дать судебные показания против Маниша.",
 "f-wd2069934": "Действие происходит в Бомбее. Биржевой аналитик Вишал ищет квартиру для себя и жены Свати. Поиски увенчались успехом - прекрасная квартира в 12-тиэтажном доме. Но квартира «нечистая» - предыдущий жилец, молодая девушка, умерла от падения с балкона. Но аналитический ум Вишала не позволяет этому обстоятельству повлиять на желание вселиться туда. Жене он об этой истории не рассказал, потому как не придал значения. В конечном счете Свати узнает о гибели девушки и ее начинают преследовать кошмары. Вишал бессилен перед проблемами психологии и для того, чтобы сохранить начинающую сходить с ума жену, ему придется пройти семь кругов ада и познать чудовищную истину..",
 "f-wd20001840": "Жадный застройщик выкупил территорию под новый микрорайон, но никак не может согнать с земли местных жителей, живущих маленькой, но дружной коммуной. Громилы застройщика во главе со злобным белым гигантом Раккой крушат хибары, но получают отпор лишь после того, как попытались срубить священное дерево. Духи, защищавшие дерево, дают местному парню, который работает физруком в школе, способности супергероя. Он и раньше владел восточными единоборствами. Его папа учился в Шаолине и показал сыну пару приёмов, теперь же Аман Диллон может летать как птица и бегать с невероятной скоростью. Теперь он — герой в маске, Летающий Джатт. Одна беда — злодей Ракка тоже человек непростой.",
 "f-wd7462497": "После смерти матери и появления мачехи Амрита Джейшанкар уходит в себя. Психолог советует отцу Амриты заняться лечением девушки, отец же откупается чеком на благотворительность. Позже Амрита знакомится с четверкой друзей – Зубином, Караном, Душантом и Таней. И начинаются их совместные пьянки, гулянки, иногда и употребление наркотиков, пока все не выходит из-под контроля. Увлекшись очередным развлечением, друзья убивают двух человек. Вскоре объявляется полицейский, требующий за закрытие дела огромную сумму. После долгих размышлений, где же взять такие деньги, друзья решают инсценировать похищение Эми и потребовать нужную сумму от ее отца. Тут и начинают разворачиваться события и, как всегда, не согласно разработанному плану.",
 "f-wd64768529": "Закадычные друзья детства Бавра и Каттани занимаются кражами невест ради процветания бизнеса своего босса Гуньи, который создал целую компанию на этом поприще. Однажды, они получают от него приказ похитить милую девушку по имени Рухи. На первый взгляд вроде нет ничего сложного, но чем дольше девушка проводит в их компании в качестве похищенной жертвы, тем больше парни начинают подозревать, что с виду миловидная девушка, на самом деле, одержима зловещим духом могущественной ведьмы Мудьяпери...",
 "f-wd59725832": "Фильм рассказывает о Майкле, главаре банды и бывшем футболисте, который по воле случая становится тренером женской команды по футболу. Он сталкивается с тем, что девушки из команды не воспринимают его всерьёз из-за криминальной деятельности. Вдобавок его преследует враг, желающий свести с ним счёты и помешать выиграть кубок.",
 "f-wd19807569": "В конце XVII века могольский падишах Аурангзеб после разграбления маратхами порта Сурат решает завоевать Южную Индию. Маратхский император Шиваджи приказывает генералу Танаджи Малусару любой ценой отвоевать крепость Синхагад и сдержать вторжение моголов, а те, в свою очередь, посылают боевого командира Удайбхана. Грядёт великая битва.",
 "f-wd779318": "Дочь владельца киностудии Зубейда с детства мечтает стать актрисой. Однако отец запретил ей сниматься в кино и выдал замуж за сына своего друга. Вскоре муж дает ей развод и уезжает в Пакистан. Спустя некоторое время подруга Зубейды знакомит её с Виджендрой, привлекательным правителем княжества. В жизнь Зубейды приходит любовь и она наполняется смыслом. Но оказывается князь женат и не собирается разводиться со своей женой Мандирой Деви. Зубейда соглашается стать его второй женой.",
 "f-wd1045889": "Таэко вспоминает времена, когда она была маленькой и училась в школе в далеком 1966 году. Она расставляет по полочкам свои воспоминания и пытается принять трудное решение о будущем.",
 "f-wd2308266": "Герой фильма, 8-летний мальчуган, обещал непременно вернуть школьному другу тетрадь с домашним заданием. Пересилив ребяческий страх, он шагает в ночную тьму, чтоб отыскать жилище приятеля в чужом, незнакомом ему селении. Мальчик ведет себя по-рыцарски, по-мужски, покоряет добротой, отзывчивостью и совсем не детской ответственностью.",
 "f-wd276343": "Микаэль Блумквист — талантливый журналист, который верой и правдой добивается справедливости в самых скандальных делах — неожиданно терпит фиаско в своей деятельности, в результате чего вынужден отбыть срок лишения свободы.В то же время влиятельный человек Хенрик Вангер поручает ему дело о пропаже его племянницы, которая таинственным образом исчезла из имения Вангеров, и о которой вот уже множество лет нет никаких новостей. А попытки Хенрика разыскать родственницу так же не приводят к положительным результатам.",
 "f-wd589953": "Это история, происходившая в Датском королевстве в середине 18-го столетия. Юная королева Каролина-Матильда ненавидит своего супруга — психически больного короля Кристиана VII, который предпочитает проституток ее обществу. Появление в свите короля немецкого врача-вольнодумца Иоганна Фридриха Струэнзе вносит серьезные коррективы не только в жизнь Каролины, влюбляющейся в красавца доктора, но и в жизнь датчан — Струэнзе оказывает серьезное влияние на короля, который постепенно преобразовывает правительство. К сожалению, роман королевы и врача обречен, поскольку мачеха Кристиана не в восторге от перемен в Копенгагене.",
 "f-wd29168508": "Стендап-комик теряет свою жену, оперную певицу, и остается с двухлетней дочерью, у которой обнаруживается необычный дар.",
 "f-wd1342900": "Одиннадцатилетний Ингмар живёт вместе с матерью, которая больна туберкулезом, и со старшим братом. Отец по делам службы находится в Африке. Чтобы избавить мать от забот и дать ей немного подлечиться, парнишку отправляют на лето к дяде в отдалённый посёлок, где всё ему чуждо и непривычно. Но именно там Ингмар знакомится с Сагой, своей ровесницей, воспринимая её искреннюю влюблённость просто как мимолетную детскую причуду.  После возвращения Ингмара в город вскоре в больнице умирает его мать — и дядя окончательно забирает мальчика к себе. Ингмар ещё обостреннее, чем раньше, чувствует собственную неприкаянность, лишается прежних надежд и иллюзий, называя свою жизнь «собачьей».",
 "f-wd1637024": "В фильме не говорят ни слова, а только флиртуют и кружатся в танце, ревнуют и мирятся. Сутенеры и фашисты, хиппи и старые девы проводят вечера в небольшом дансинге, а грохот европейской истории, изредка доносящийся с улицы, лишь на мгновения отвлекает их от вечного танца, который и есть жизнь, которая и есть танец.",
 "f-wd221354": "Три женщины оказались в роддоме. Две из них мечтают родить ребенка, еще одна — хочет от него избавиться. Однако у жизни на все свои планы.",
 "f-wd1254081": "После закрытия судоверфи бывшие местные рабочие время от времени встречаются, чтобы обсудить свое сложное жизненное положение.",
 "f-wd1471325": "Дочь состоятельного графа Юлия влюбляется в лакея отца и решает уйти с ним из дома родителей, чтобы избежать гнева окружающих.",
 "f-wd1170354": "Банда головорезов похищает молодого высокопоставленного чиновника и держит его в заложниках, требуя у властей в обмен выдачи своего плененного главаря. Золотую Ласточку посылают разделаться с бандитами и заодно освободить заложника, который приходится ей братом. Хотя она достойно выдерживает неравную борьбу, враг поражает ее смазанным ядом дротиком. На помощь ей приходит нищий, который, на самом деле, оказывается переодетым мастером кунг-фу. Вместе с ним она разрабатывает план освобождения своего брата.",
 "f-wd300356": "Странствующий ученый Лин забредает на ночь глядя в волшебный лес, где встречает девушку-привидение по имени Сиан. Мимолетная встреча становится началом бурного романа, но у Сиан есть злобная наставница, которая не одобряет романов между людьми и призраками. Даже защитник Лина, отважный меченосец-таоист, с которым юноша познакомился по дороге, хоть и сочувствует влюбленным, также считает, что их любовь обречена.",
 "f-wd1753074": "8 июня 2005 года. Отборочный матч к чемпионату мира по футболу, в котором сборная Ирана, в случае победы над сборной Бахрейна, может обеспечить себе путёвку в Германию. Девушки наравне с мужчинами хотят поддержать национальную команду и пытаются попасть на стадион, на котором нет места женщине…",
 "f-wd2060452": "У обычной домохозяйки Глории появляются серьезные проблемы. Ее муж страстно увлекается бывшей певичкой; один из сыновей с удовольствием продает наркотики, а другой заводит бурные романы с отцами своих одноклассников. Положение становится еще хуже, когда из-за странного стечения обстоятельств взбалмошная Глория оказывается замешанной в убийстве и попытке продать поддельные дневники Гитлера.",
 "f-wd200432": "Старый рыбак приносит профессору Яно странное существо напоминающее головастика и мимоходом жалуется что резко снизился улов. Скоро в теленовостях показывают, как что-то гиганских размеров переламывает напополам судно, и сын профессора Кен находит сходство с «головастиком» рыбака. Профессор вместе с сыном отправляются исследовать побережье.  Они обнаруживают гиганского «головастика». Кен называет существо Хедора. При дальнейшее изучении выясняется что Хедоры питаются загрязнениями из залива, мелкие Хедоры-головастики могут сформироваться в огромную Хедору, котрая может принимать любые формы и даже умеет летать. Скоро гигантский Хедора появляется в заливе Сагами. Чудище забирается на трубы местной фабрики и словно завзятый курильщик затягивается из них дымком. Годзилла бросает вызов новому монстру. В схватке двух титанов начинают гибнуть люди. Кто же остановит чудовище?",
 "f-wd2497009": "Сиквел к «Кулаку ярости» с Брюсом Ли начинается там же, где заканчивается оригинальный фильм. Оставшиеся три соратника героя Брюса Ли, убитого в первом фильме, уезжают из Шанхая на Тайвань, чтобы продолжить там свою борьбу с японскими захватчиками. В это время там появляется новый начальник-японец, большой специалист по боевым искусствам, который решает взять под свою юрисдикцию все школы китайских боевых искусств, что, естественно, не нравится китайцам.",
 "f-wd494594": "Согласно древней корейской легенде, ужасные создания Имуги вернутся и разрушат планету. Репортер Итан Кендрик, занимающийся расследованием обстоятельств дела, приходит к выводу, что ему может помочь девушка Сара, пораженная таинственной болезнью. Тем временем Имуги приближаются к Лос-Анджелесу, сея на своем пути хаос и разруху. Успеют ли Итан и Сара спасти жителей города, пока еще не слишком поздно…",
 "f-wd26252639": "Спасая ребёнка из горящего здания, пожарный Ким Джа-хон погибает героической смертью. И тут же три ангела смерти сопровождают его в мир мёртвых, где смертному предстоит пройти 7 судов и держать ответ перед 7-ю Богами. Ангелы будут его защитниками, и если Джа-хона признают безгрешным, он получит возможность реинкарнироваться и начать новую жизнь.",
 "f-wd3928247": "Анхела приходит в себя на корабле посреди океана. После вспышки эпидемии неизвестного вируса, превращающего людей в зомби, ученые решили изолировать инфицированных, но не заболевших людей, чтобы исследовать природу заразы. На специально оборудованном бывшем нефтяном танкере есть все необходимое оборудование для проведения лабораторных экспериментов. Но, ни ученые, ни команда даже не догадываются, что их ждет. Ведь инфицированные несут в себе гибель для всего человечества.",
 "f-wd673850": "Фильм рассказывает о чуде, случившемся благодаря Рабе в 1937 году в нанкинском хаосе.",
 "f-wd1761192": "Вторая часть знаменитой трилогии о распаде семьи.",
 "f-wd18709329": "Правдивая история клана Пуччио. Эта семья похищала и убивала людей в 1980-х.",
 "f-wd111262699": "В постапокалиптическом мире изменение климата создало бесконечную зиму, а жестокая гражданская война угрожает цивилизации. Сюжет повествует о шести солдатах, которые отправляются на опасную миссию через замёрзшее море, чтобы перевезти пакет, который мог бы наконец положить конец войне.",
 "f-wd118313105": "Таинственная сила уничтожает человечество. История о новой угрозе разворачивается в Барселоне, расширяя вселенную блокбастера «Птичий короб».",
 "f-wd1216829": "На дворе 1973 год, и в Испании бушует франкистская диктатура. Вопреки запретам простой коммивояжер Альфредо собирается пойти на явное преступление — снять 8 эротических «образовательных» фильмов и переправить их в лояльную Скандинавию. Он и подумать не мог, что его жена Кармен, «сыгравшая» в фильмах главные роли, в северных странах станет порнозвездой, и из Дании к Альфредо пожалует съемочная группа, чтобы помочь снять ему вдохновленный творчеством Бергмана фильм «Торремолинос 73»…",
 "f-wd730555": "Много лет назад в этом доме произошла трагедия: мужчина убил жену, а судьба их шестилетнего сына Тосио неизвестна, мальчик исчез. Умирая, несчастная женщина прокляла убийцу и место, где она встретила смерть. Теперь яростный призрак несёт смерть всем, кто осмелился приблизиться к его владениям.",
 "f-wd1156769": "Волна самоубийств захватывает Токио после того как 54 школьницы бросились под поезд в метро. После этого полиция обнаруживает странный веб-сайт, отслеживающий самоубийства до того как они происходят.",
 "f-wd16635884": "В 1994 году двое детей близнецов были найдены зверски убитыми в летнем загородном доме. Ряд фактов указывал на причастность к делу группы молодых студентов, но расследование было прекращено, после того как местный отшельник признал себя виновным в этом инциденте. 20 лет спустя это дело попадает на стол Карлса Мёрка, который начинает подозревать, что в нем что-то не так...",
 "f-wd2058835": "Трансильвания, 1893 год. Молодой библиотекарь Джонатан Харкер прибывает в деревню Пассо Борго, нанявшись на работу к местному аристократу графу Дракуле. Познакомившись со своим загадочным хозяином, Джонатан вскоре узнает истинную натуру графа и понимает, в какой опасности находится он сам и его жена Мина. Одни за другим вокруг таинственно погибают люди. Кажется, только Авраам ван Хельсинг, уже встречавшийся на пути графа, способен изменить их печальную участь.",
 "f-wd559071": "Человек в маске, представленный зрителю как Учиха Мадара, решает завладеть силой девятихвостого, для чего проникает в Коноху, где сталкивается с Наруто и Сакурой. С помощью силы глаз использует технику «Цукиёми», которая погружает героев в параллельную реальность, где всё наоборот, родители Наруто живы, Сакура дочь героев деревни, Саске никуда не уходил, Акацки защищают Коноху, и всё кажется идеально. Вот только тот ли это мир, который хочет защитить Наруто, его ли это жизнь? Вместе с Сакурой, Наруто должен найти ответ на эти вопросы и разобраться с человеком в маске, который смог заполучить в союзники таинственного парня в маске из альтернативной реальности.",
 "f-wd42293829": "Ниша — шестнадцатилетняя девушка, ведущая двойную жизнь. Дома она примерная дочь, живущая по правилам, установленным в её пакистанской семье. В кругу друзей она ничем не отличается от обычных норвежских подростков. Когда отец застаёт девушку в комнате с бойфрендом, её жизнь резко меняется.",
 "f-wd542532": "Фильм основывается на легенде о Белой Змее, которая хвалит смелую любовь, между змеиным духом Бай Сужен и ее мужем-человеком Сю Сяном. Колдун Фахай изображен монахом, который верит, что любой демон это зло. Его вера приводит к тому, что он разрушает семью Бай Сужен и Сю Сяна. Шенг Хуанг исполнит роль змеи, а Рэймонд Лам ее мужа. Актриса Шарлин Чой играет зеленую змею — доверенное лицо белой змеи. Остальные кадры показывают роман между зеленой змеей и Нэнгреном.",
 "f-wd1133999": "Китай, начало 1970-х. Во время Культурной революции старшеклассница Цзин — одна из многих представителей «образованной молодежи» отправлена на «перевоспитание» в деревню. Там она встречает геолога Суня. Отец Суня занимает высокий военный пост. Отец Цзин — политический заключенный, ее мать, всеми силами пытается свести концы с концами, выполняя тяжелую работу.",
 "f-wd27958503": "Старшеклассник Итиго Куросаки с детства был способен видеть призраков. Однажды, встряв в схватку со странным призрачным монстром, Итиго погибает, но оказывается возвращен к жизни ангелом смерти по имени Рукия. Из-за нелепой случайности Рукия лишается всех своих сил, которые попадают к Итиго. Отныне Итиго — новый синигами и борец со злыми духами, а Рукия — простая смертная девушка, которая вынуждена стать наставником для молодого охламона.",
 "f-wd112897629": "Ханамичи Сакураги - хулиган, у которого долгое время не ладилось с девушками. Поступив в старшую школу Сёхоку, Ханамичи заинтересовался девушкой по имени Харуко, которая любит баскетбол.",
 "f-wd49729": "Семья переезжает в новый дом, и беременная жена с трудом справляется с работой по дому. Ещё она должна изо всех сил работать на швейной машинке — только так они с мужем могут прокормить себя и детей. И тогда муж нанимает служанку.",
 "f-wd7549606": "Однажды дождливым утром ученица начальных классов Со-вон отправляется в школу рядом с домом. Она должна была идти вместе с другом, но тот побежал с мальчишками. Отец девочки работает на местной фабрике, а мама управляет магазином канцтоваров, расположенным под домом. Через несколько часов после ухода дочери отец получает звонок из полиции — Со-вон изнасиловали, девочка в больнице в тяжёлом состоянии.",
 "f-wd732436": "В фильме рассказывается о жизни Диего Марадоны. Хронологический принцип не соблюдается. Хроника сочетается с диалогами, музыкой, мини-роликами. Отдельно освещены борьба с наркотической зависимостью, семья, дружба с Уго Чавесом и Фиделем Кастро, политические взгляды, история с «рукой Бога».",
 "f-wd1984591": "Действие фильма разворачивается в Вьетнаме, в мае 1954 года во время Первой индокитайской войны за два месяца до подписания в Женеве соглашения о перемирии. Фильм участвовал в основной конкурсной программе 18-го Каннского международного кинофестиваля, где получил приз за лучший сценарий.",
 "f-wd22000111": "История, основанная на реальных событиях, и раскрывающая взаимоотношения бывшего секретного агента Франсиско Паэсы и Луиса Рольдана, бывшего главы Гражданской гвардии. Франсиско Паэса, ответственный за проведение важнейшей операции против ЭТА, оказывается вовлечён в дело о вымогательстве в разгар кризиса с грязной игрой правительства против ЭТА и вынужден бежать из страны. Вернувшись спустя несколько лет, он понимает, что его жизнь разрушена. В данных обстоятельствах его посещает Луис Рольдан со своей женой и предлагает ему миллион долларов, если он поможет сохранить им 1.5 миллиарда песет, незаконно выведенных из государственного бюджета. Паэса видит в этом возможность отомстить испанскому правительству и вместе со своим закадычным другом Хесусом Камоэсом разрабатывают беспроигрышный план.",
 "f-wd33642863": "Вернувшись после гражданской войны с парализованной рукой, Мартин узнаёт, что его младший брат внезапно начал расти и уже вымахал за два с половиной метра. Чтобы прокормить семью в стране, которая опустошена войной, Мартин убеждает брата согласиться выступать на потеху толпе, а сам становится его антрепренёром. Однако, всё меняется когда братья понимают, что гигантизм - это опасная болезнь и гиганты долго не живут.",
 "f-wd2426670": "Служащий токийского банка Сукити Сугияма в одиночку вырастил двух дочерей после того, как их мать бросила семью и уехала с другим мужчиной. Старшая дочь, Такако, временно переехала к отцу с годовалым ребёнком: её брак с преподавателем Нуматой оказался не слишком удачным. Младшая, Акико, доставляет много беспокойства отцу и сестре своими поздними возвращениями, а однажды её даже задерживает полиция. Для блужданий Акико по городу есть веские основания: она ищет своего парня, чтобы сообщить ему о беременности.",
 "f-wd4356108": "К середине 19-го века могущество сёгунов стало ослабевать. Вместе с ним подходит к завершению почти тысячелетняя история самураев — элиты японского феодального рыцарства.  Эпицентр этого драматического перелома пришелся на Киото и гарнизон его защитников. Перед многими встал выбор: перейти на сторону мятежников или пожертвовать жизнью.",
 "f-wd10288763": "В основе картины — популярная легенда о том, как сорок семь самураев сделали харакири, отстаивая честь своего господина.",
 "f-wd67597432": "После полного солнечного затмения тёмная сила окутывает Землю, и воины в матросках вынуждены снова объединиться, чтобы вернуть миру свет...",
 "f-wd10862358": "В послевоенном Гонконге легендарный великий мастер Ип Ман вскоре после событий, связанных с, казалось бы, простым соперничеством между различными стилями кунг-фу, оказывается поневоле втянутым в тёмный и опасный преступный мир триад. Теперь, чтобы защитить жизнь и честь, ему не остаётся ничего, кроме как сразиться в последний раз…"
};
